def route_files(layout, params, ctx):
    for path in sorted(layout["files"]):
        if layout["keys"].get(path) is not None:
            continue
        parts = path.split("/")
        study, name = parts[0], parts[-1]
        d = "/" + "/".join(parts[1:-1]) + "/"
        matched = []
        if "/adam/" in d:
            matched.append((1, study + "/adam/" + name))
        if "/sdtm/" in d:
            matched.append((2, study + "/sdtm/" + name))
        if len(matched) == 1:
            layout["keys"][path] = matched[0][1]
            layout["vars"]["reason:" + path] = "rule " + str(matched[0][0])
        else:
            layout["keys"][path] = "error/" + path
            layout["vars"]["reason:" + path] = "no rule" if not matched else "multiple rules"
    return layout

def move_and_tag(transfers, params, ctx, aws):
    if_exists = ctx["delivery"]["if_exists"]
    results = []
    for t in transfers:
        reason = params["reason:" + t["path"]]
        is_error = t["target_key"].startswith("error/")
        res = {"path": t["path"], "key": t["target_key"], "status": "failed", "detail": reason}
        try:
            aws.s3_destination.copy({"Bucket": t["source_bucket"], "Key": t["source_key"]}, t["target_bucket"], t["target_key"],
                                    SourceClient=aws.s3_source)
            head = aws.s3_destination.head_object(Bucket=t["target_bucket"], Key=t["target_key"])
            if head["ContentLength"] != t["size"]:
                res["detail"] = reason + "; size mismatch after copy"
                results.append(res)
                continue
            aws.s3_source.delete_object(Bucket=t["source_bucket"], Key=t["source_key"])
        except Exception as exc:
            res["detail"] = reason + "; " + type(exc).__name__ + ": " + str(exc)
            results.append(res)
            continue
        if not is_error:
            try:
                aws.s3_destination.put_object_tagging(Bucket=t["target_bucket"], Key=t["target_key"],
                                                      Tagging={"TagSet": [{"Key": "ADDITIONAL_TAG", "Value": t["path"]}]})
            except Exception as exc:
                aws.log.warning("tagging failed for %s: %s", t["target_key"], exc)
        res["status"] = "moved_to_error" if is_error else "moved"
        aws.log.info("%s -> %s [%s] (if_exists=%s)", t["source_key"], t["target_key"], reason, if_exists)
        results.append(res)
    return results
